const input = $input.first().json;
function buildQs(obj) { return Object.entries(obj).filter(([k,v]) => v !== undefined && v !== null).map(([k,v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&'); }

const action = input.action || '';
// Anzeigename der fragenden Person, vom Agenten gesetzt (search_issues seit 1.3.0,
// create_issue und update_issue seit 1.4.0). Damit werden "ich", "me", "mir" als
// Bearbeiter aufgeloest, statt als Suchbegriff an Jira zu gehen: "me" traf am
// 09.09.2026 unscharf Martina Rechner-Meilinger, 14 Tickets waren falsch zugewiesen.
const CALLER_NAME = String(input.caller_name || '').trim();
const SELBST_RE = /^(me|myself|self|ich|mir|mich|mein|meins|current ?user|currentuser\(\))$/i;

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pgHeaders = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

const allCreds = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.jira&select=cred_key,cred_value',
  headers: pgHeaders
});
const creds = {};
for (const c of (allCreds || [])) creds[c.cred_key] = c.cred_value;
if (!creds.atlassian_email || !creds.atlassian_api_token || !creds.atlassian_site) {
  return [{ json: { error: 'Jira credentials not configured. Need atlassian_email, atlassian_api_token, atlassian_site.' } }];
}

const site = creds.atlassian_site.replace(/^https?:\/\//, '').replace(/\/$/, '');
const API = 'https://' + site + '/rest/api/3';
const basic = Buffer.from(creds.atlassian_email + ':' + creds.atlassian_api_token).toString('base64');
const authHeaders = { 'Authorization': 'Basic ' + basic, 'Accept': 'application/json' };
const jsonHeaders = { ...authHeaders, 'Content-Type': 'application/json' };

// Erwaehnungen: "@Vorname Nachname" (nur am Anfang oder nach einem Leerzeichen,
// Mailadressen bleiben unberuehrt) und "[~accountId:...]" werden zu echten
// Jira-Mentions mit Benachrichtigung. Vorher kam "[~accountId:...]" als Text an,
// und die erwaehnte Person hat nichts erfahren (SLT, 04.09.2026).
async function userByAccountId(id) {
  try {
    const u = await helpers.httpRequest({ method: 'GET', url: API + '/user?' + buildQs({ accountId: id }), headers: authHeaders });
    return u && u.displayName ? u.displayName : null;
  } catch (e) { return null; }
}
async function resolveMention(name) {
  // Gleiche Regeln wie resolveUser (1.4.0): Selbstbezug ueber den Anzeigenamen der
  // fragenden Person, sonst nur ein exakter Treffer; ein einziger unscharfer Treffer
  // wird nicht mehr still uebernommen ("@me" traf sonst irgendwen).
  let s = String(name || '').trim();
  const selbst = SELBST_RE.test(s);
  if (selbst) {
    if (!CALLER_NAME) throw new Error('Erwaehnung @' + s + ' meint die fragende Person, ihr Name ist in diesem Aufruf aber nicht bekannt. Vollen Namen schreiben.');
    s = CALLER_NAME;
  }
  const r = await helpers.httpRequest({ method: 'GET', url: API + '/user/search?' + buildQs({ query: s, maxResults: '10' }), headers: authHeaders });
  const items = (Array.isArray(r) ? r : []).filter(u => u.accountType !== 'app');
  const exakt = items.filter(u => String(u.displayName || '').toLowerCase() === s.toLowerCase());
  if (exakt.length === 1) return { id: exakt[0].accountId, text: '@' + exakt[0].displayName };
  if (selbst && exakt.length === 0 && items.length === 1) return { id: items[0].accountId, text: '@' + items[0].displayName };
  if (items.length === 0) throw new Error('Erwaehnung @' + s + ': niemand gefunden. Mit list_users den genauen Namen holen.');
  throw new Error('Erwaehnung @' + s + (exakt.length > 1 ? ' ist mehrdeutig: ' : ' trifft nicht genau, Kandidaten: ') + (exakt.length ? exakt : items).slice(0, 8).map(u => u.displayName).join(', ') + '. Vollen Namen schreiben oder [~accountId:...] verwenden.');
}
async function textToAdf(text) {
  if (!text) return null;
  const content = [];
  const lines = String(text).split(/\r?\n/);
  const re = /\[~accountId:([^\]]+)\]|(^|\s)@([A-Za-z\u00C0-\u017F][\w\u00C0-\u017F.'-]*(?: [A-Z\u00C0-\u00DE][\w\u00C0-\u017F.'-]*)?)/g;
  for (let li = 0; li < lines.length; li++) {
    if (li > 0) content.push({ type: 'hardBreak' });
    const line = lines[li];
    let last = 0; let m;
    re.lastIndex = 0;
    while ((m = re.exec(line)) !== null) {
      let vor = line.slice(last, m.index);
      let mention;
      if (m[1]) {
        const id = m[1].trim();
        const dn = await userByAccountId(id);
        mention = { id, text: '@' + (dn || id) };
      } else {
        vor += m[2];
        mention = await resolveMention(m[3].trim());
      }
      if (vor) content.push({ type: 'text', text: vor });
      content.push({ type: 'mention', attrs: { id: mention.id, text: mention.text } });
      last = m.index + m[0].length;
    }
    const rest = line.slice(last);
    if (rest) content.push({ type: 'text', text: rest });
  }
  if (!content.length) content.push({ type: 'text', text: String(text) });
  return { type: 'doc', version: 1, content: [{ type: 'paragraph', content }] };
}

function adfToText(adf) {
  if (!adf) return '';
  if (typeof adf === 'string') return adf;
  let out = '';
  function walk(n) {
    if (!n) return;
    if (n.type === 'text' && n.text) out += n.text;
    if (n.type === 'mention' && n.attrs && n.attrs.text) out += n.attrs.text;
    if (n.type === 'hardBreak') out += '\n';
    if (Array.isArray(n.content)) n.content.forEach(walk);
    if (n.type === 'paragraph' || n.type === 'heading') out += '\n';
  }
  walk(adf);
  return out.trim();
}

function truncate(text, max) {
  max = max || 5000;
  if (text.length > max) return text.substring(0, max) + '\n\n... (truncated, ' + text.length + ' chars total)';
  return text;
}

function issueUrl(key) {
  return 'https://' + site + '/browse/' + key;
}

function fmtIssueLine(iss) {
  const f = iss.fields || {};
  let line = iss.key;
  if ('status' in f) line += ' [' + (f.status ? f.status.name : '?') + ']';
  if ('issuetype' in f) line += ' [' + (f.issuetype ? f.issuetype.name : '?') + ']';
  line += ' ' + (f.summary || '');
  if ('assignee' in f) line += ' (@' + (f.assignee ? f.assignee.displayName : 'unassigned') + ')';
  return line;
}

// --- Custom-Felder in die vom Feld erwartete Form bringen ---
// Ein Mehrfachauswahl-Feld erwartet eine Liste ([{value: ...}]), ein
// Einfachauswahl-Feld ein Objekt ({value: ...}), ein Textfeld einen String.
// Frueher musste das Modell die Form raten; ein Objekt fuer ein Listenfeld ergab
// einen 400er, dessen Ursache es dann frei interpretiert hat.
async function loadCreateMetaFields(projectKey, issuetypeName) {
  const pk = String(projectKey || '').toUpperCase();
  const tlist = await ladeTypen(pk);
  // Nur der genannte Typ. Der fruehere Rueckfall auf den ersten Typ der Liste
  // lieferte die Pflichtfelder eines fremden Typs (SLT, 09.09.2026).
  const t = tlist.find(x => x.name && x.name.toLowerCase() === String(issuetypeName || '').toLowerCase());
  if (!t) return {};
  const meta = await helpers.httpRequest({ method: 'GET', url: API + '/issue/createmeta/' + encodeURIComponent(pk) + '/issuetypes/' + encodeURIComponent(t.id), headers: jsonHeaders });
  const flist = meta.fields || meta.values || [];
  const out = {};
  for (const f of flist) {
    const id = f.fieldId || f.key;
    if (id) out[id] = f;
  }
  return out;
}

function shapeFieldValue(val, spec) {
  const sch = (spec && spec.schema) || {};
  const isArray = sch.type === 'array';
  const item = isArray ? (sch.items || '') : (sch.type || '');
  // null oder leer heisst: Feld leeren. Jira erwartet dafuer null, nicht [null].
  if (val === null || val === undefined || val === '') return null;
  const wrap = function (v) {
    if (v === null || v === undefined) return v;
    if (typeof v === 'object') return v;
    if (item === 'number') { const zahl = Number(v); if (!isNaN(zahl)) return zahl; }
    const s = String(v);
    if (item === 'option' || item === 'group' || item === 'version' || item === 'component' || item === 'priority' || item === 'resolution') return { value: s };
    if (item === 'user') return { accountId: s };
    return s;
  };
  if (isArray) return (Array.isArray(val) ? val : [val]).map(wrap);
  if (Array.isArray(val)) return wrap(val[0]);
  return wrap(val);
}

async function shapeCustomFields(cf, projectKey, issuetypeName, presetMeta) {
  try {
    const metaFields = presetMeta || await loadCreateMetaFields(projectKey, issuetypeName);
    for (const k of Object.keys(cf)) {
      if (metaFields[k]) cf[k] = shapeFieldValue(cf[k], metaFields[k]);
    }
  } catch (e) { /* ohne Schema unveraendert weiterreichen */ }
  return cf;
}

// --- Feldindex: Klarname oder Id -> Feld (einmal je Lauf, GET /field) ---
// Das Modell kennt die Felder so, wie Jira sie anzeigt ("Massnahme"), die API
// will customfield_10098. Ohne Index musste es raten oder die Id nachschlagen
// lassen (SLT, 08.09.2026). Gleichnamige Felder bleiben mehrdeutig und werden
// nicht still aufgeloest.
let _fieldIdx = null;
// Das Modell schreibt Feldnamen oft ohne Umlaute ("Massnahme" statt "Maßnahme").
// Deshalb neben dem echten Namen einen normalisierten Schluessel fuehren.
function normFeldName(s) {
  return String(s || '').trim().toLowerCase()
    .replace(/\u00df/g, 'ss').replace(/\u00e4/g, 'ae').replace(/\u00f6/g, 'oe').replace(/\u00fc/g, 'ue')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}
async function fieldIndex() {
  if (_fieldIdx) return _fieldIdx;
  const idx = { list: [], byId: {}, byName: {}, byNorm: {} };
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/field', headers: authHeaders });
    for (const f of (Array.isArray(r) ? r : [])) {
      if (!f || !f.id) continue;
      idx.list.push(f);
      idx.byId[String(f.id).toLowerCase()] = f;
      const nm = String(f.name || '').trim().toLowerCase();
      if (!nm) continue;
      if (!idx.byName[nm]) idx.byName[nm] = [];
      idx.byName[nm].push(f);
      const nn = normFeldName(f.name);
      if (nn) { if (!idx.byNorm[nn]) idx.byNorm[nn] = []; if (!idx.byNorm[nn].includes(f)) idx.byNorm[nn].push(f); }
    }
  } catch (e) { /* ohne Index gelten nur Ids */ }
  _fieldIdx = idx;
  return idx;
}
function resolveField(idx, nameOrId) {
  const s = String(nameOrId || '').trim();
  if (!s) return null;
  const k = s.toLowerCase();
  if (!idx.list.length) return /^[A-Za-z][A-Za-z0-9_]*$/.test(s) ? s : null;
  if (idx.byId[k]) return idx.byId[k].id;
  const cf = k.match(/^cf\[(\d+)\]$/);
  if (cf && idx.byId['customfield_' + cf[1]]) return 'customfield_' + cf[1];
  const hits = idx.byName[k] || [];
  if (hits.length === 1) return hits[0].id;
  if (!hits.length) {
    const nhits = idx.byNorm[normFeldName(s)] || [];
    if (nhits.length === 1) return nhits[0].id;
  }
  return null;
}
function fieldLabel(idx, id) {
  const f = idx.byId[String(id).toLowerCase()];
  return f && f.name ? f.name : id;
}
function unknownFieldError(idx, name) {
  const hits = (idx.byName[String(name).trim().toLowerCase()] || []).length
    ? idx.byName[String(name).trim().toLowerCase()]
    : (idx.byNorm[normFeldName(name)] || []);
  if (hits.length > 1) return 'Feld "' + name + '" gibt es mehrfach: ' + hits.map(f => f.name + ' (' + f.id + ')').join(', ') + '. Bitte die Id verwenden.';
  if (!idx.list.length) return 'Feld "' + name + '" konnte nicht geprueft werden, weil die Feldliste nicht geladen wurde. Nutze die Feld-Id (z. B. customfield_10098).';
  return 'Feld "' + name + '" ist in Jira nicht bekannt. Nutze list_fields, um den genauen Namen oder die Id zu finden.';
}
function fieldTypeLabel(f) {
  const sch = (f && f.schema) || {};
  let t = sch.type || (f && f.custom ? 'custom' : '?');
  if (t === 'array' && sch.items) t = 'array<' + sch.items + '>';
  if (sch.custom) t += ' (' + String(sch.custom).split(':').pop() + ')';
  return t;
}
// "fields"-Parameter: Kommaliste aus Klarnamen, Ids oder *all
async function parseFieldsParam(raw) {
  const parts = String(raw || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!parts.length) return { ids: [], all: false };
  if (parts.some(p => /^\*all$/i.test(p))) return { ids: [], all: true };
  const idx = await fieldIndex();
  const ids = [];
  for (const p of parts) {
    // Jira kennt eigene Sammelwerte (*navigable, *all). Die gehen unveraendert durch.
    if (p.charAt(0) === '*') { if (!ids.includes(p)) ids.push(p); continue; }
    const id = resolveField(idx, p);
    if (!id) return { error: unknownFieldError(idx, p) };
    if (!ids.includes(id)) ids.push(id);
  }
  return { ids, all: false };
}
function hasValue(v) {
  if (v === null || v === undefined || v === '') return false;
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === 'object') return Object.keys(v).length > 0;
  return true;
}
// Ein langes Absatzfeld darf die Ausgabe nicht sprengen, sonst faellt hinten
// die Beschreibung oder die Kommentarliste weg (Kappung bei 5000 Zeichen).
function kurz(s) {
  const t = String(s);
  return t.length > 300 ? t.slice(0, 300) + ' ...' : t;
}
function fmtFieldValue(v) {
  if (!hasValue(v)) return '';
  if (Array.isArray(v)) return v.map(fmtFieldValue).filter(Boolean).join(', ');
  if (typeof v !== 'object') return kurz(v);
  if (v.type === 'doc') return kurz(adfToText(v));
  for (const k of ['value', 'name', 'displayName', 'key']) {
    if (v[k] !== undefined && v[k] !== null) return typeof v[k] === 'object' ? fmtFieldValue(v[k]) : kurz(v[k]);
  }
  return JSON.stringify(v).substring(0, 200);
}
// Zeilen "Klarname: Wert": erst die angefragten Felder (ohne Wert steht
// "(kein Wert)", damit "leer" von "nicht abgefragt" unterscheidbar bleibt),
// dann alle weiteren customfield_* mit Wert. skip: Ids, die mit Wert schon
// anders angezeigt werden.
function extraFieldLines(idx, f, requested, skip) {
  const lines = [];
  const seen = new Set(skip || []);
  for (const id of (requested || [])) {
    if (seen.has(id) && hasValue(f[id])) continue;
    seen.add(id);
    lines.push(fieldLabel(idx, id) + ': ' + (hasValue(f[id]) ? fmtFieldValue(f[id]) : '(kein Wert)'));
  }
  for (const k of Object.keys(f)) {
    if (seen.has(k) || !/^customfield_/i.test(k) || !hasValue(f[k])) continue;
    lines.push(fieldLabel(idx, k) + ': ' + fmtFieldValue(f[k]));
  }
  return lines;
}

// --- Person -> accountId ---
// Eine accountId (mit ':' oder lang, ohne Leerzeichen und ohne '@') geht
// direkt durch, alles andere geht in die Nutzersuche und muss genau eine
// Person treffen. Vorher landete ein Name im accountId-Feld: zehnmal HTTP 400
// hintereinander (SLT, 08.09.2026).
function looksLikeAccountId(s) {
  // Atlassian: 24 Hexzeichen oder "557058:uuid". Namen ohne Leerzeichen wie
  // "Maximilian-Alexander" sind keine Ids und gehen in die Nutzersuche.
  return s.indexOf(':') >= 0 || /^[0-9a-f]{24}$/i.test(s);
}
async function resolveUser(who, what, vertraut) {
  let s = String(who || '').trim();
  const label = what || 'Nutzer';
  if (!s) return { error: label + ' fehlt.' };
  if (looksLikeAccountId(s)) return { accountId: s };
  // Selbstbezug: die fragende Person selbst. Ohne Anzeigenamen (Sub-Agent,
  // Hintergrundlauf) lieber abbrechen als irgendjemanden nehmen. Der Anzeigename
  // stammt aus dem Profil, nicht vom Modell: dort darf ein eindeutiger unscharfer
  // Treffer gelten ("Mike Gassner" findet "Michael Gassner"), wie in 1.3.0.
  if (SELBST_RE.test(s)) {
    if (!CALLER_NAME) return { error: label + ' "' + s + '" meint die fragende Person, aber ihr Name ist in diesem Aufruf nicht bekannt. Bitte den vollen Namen oder die Mailadresse angeben.' };
    s = CALLER_NAME; vertraut = true;
  }
  if (s.length < 3) return { error: label + ' "' + s + '" ist zu kurz fuer eine Nutzersuche. Bitte vollen Namen oder Mailadresse angeben.' };
  let items = [];
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/user/search?' + buildQs({ query: s, maxResults: '10' }), headers: authHeaders });
    items = (Array.isArray(r) ? r : []).filter(u => u.accountType !== 'app');
  } catch (e) { return { error: 'Nutzersuche fuer "' + s + '" fehlgeschlagen: ' + e.message }; }
  const low = s.toLowerCase();
  const exakt = items.filter(u => String(u.displayName || '').toLowerCase() === low || String(u.emailAddress || '').toLowerCase() === low);
  if (exakt.length === 1) return { accountId: exakt[0].accountId, displayName: exakt[0].displayName };
  if (vertraut && exakt.length === 0 && items.length === 1) return { accountId: items[0].accountId, displayName: items[0].displayName };
  if (!items.length) return { error: 'Kein Jira-Nutzer fuer "' + s + '" gefunden. Nutze list_users mit Namen oder Mailadresse und gib die accountId an.' };
  // Kein exakter Treffer: nie still den einzigen unscharfen nehmen (1.3.0 tat das,
  // "me" wurde Martina Rechner-Meilinger). Kandidaten nennen, Modell muss waehlen.
  const kand = (exakt.length ? exakt : items).slice(0, 8);
  return { error: label + ' "' + s + '" trifft nicht genau. ' + (kand.length === 1 ? 'Meinst du ' : 'Kandidaten: ') +
    kand.map(u => u.displayName + (u.emailAddress ? ' (' + u.emailAddress + ')' : '')).join(', ') +
    (kand.length === 1 ? '? Wenn ja, den vollen Namen oder die Mailadresse angeben.' : '. Bitte den vollen Namen oder die Mailadresse angeben, oder die accountId nutzen.') };
}
// parent: Schluessel, Objekt {key}, Ticket-Adresse (.../browse/OM-1) oder leer
function parentKey(p) {
  if (p === undefined || p === null) return '';
  if (typeof p === 'object') return String(p.key || p.id || '').trim();
  let s = String(p).trim();
  if (s.startsWith('{')) { try { const o = JSON.parse(s); return String(o.key || o.id || '').trim(); } catch (e) {} }
  const m = s.match(/\/browse\/([A-Z][A-Z0-9_]+-\d+)/i);
  if (m) return m[1].toUpperCase();
  return s;
}
// Vorgangstypen eines Projekts, einmal je Aufruf
let _typenCache = {};
async function ladeTypen(projectKey) {
  const pk = String(projectKey || '').toUpperCase();
  if (_typenCache[pk]) return _typenCache[pk];
  const types = await helpers.httpRequest({ method: 'GET', url: API + '/issue/createmeta/' + encodeURIComponent(pk) + '/issuetypes', headers: jsonHeaders });
  _typenCache[pk] = types.issueTypes || types.values || [];
  return _typenCache[pk];
}
function typLabel(t) {
  const lvl = (t.hierarchyLevel !== undefined && t.hierarchyLevel !== null) ? t.hierarchyLevel : (t.subtask ? -1 : 0);
  return t.name + ' (Ebene ' + lvl + (lvl < 0 ? ', braucht parent' : (lvl > 0 ? ', kann Aufgaben enthalten' : '')) + ')';
}
// Nutzerfelder in custom_fields: Name oder Mail -> accountId, bevor die Form
// aus dem Schema gesetzt wird
async function resolveUserFields(cf, meta) {
  for (const k of Object.keys(cf)) {
    const spec = meta[k] || {};
    const sch = spec.schema || {};
    const isUser = sch.type === 'user' || (sch.type === 'array' && sch.items === 'user');
    if (!isUser) continue;
    const vals = Array.isArray(cf[k]) ? cf[k] : [cf[k]];
    const out = [];
    for (const v of vals) {
      if (v && typeof v === 'object') { out.push(v); continue; }
      const u = await resolveUser(v, 'Feld ' + (spec.name || k));
      if (!u.accountId) return { error: u.error };
      out.push(u.accountId);
    }
    cf[k] = Array.isArray(cf[k]) ? out : out[0];
  }
  return { cf };
}

// --- JQL vorbereiten ---
// 1. currentUser(): die API laeuft als Service-Konto, deshalb meint
//    currentUser() dort die falsche Person (bei SLT ein Serverfehler). Mit
//    caller_name wird die fragende Person gesucht und ihre accountId eingesetzt.
// 2. Klarnamen von Custom-Feldern vor einem Operator ("Massnahme" = ...) werden
//    zu cf[NNNN], aber nur bei eindeutigem Treffer im Index. Standardfelder
//    bleiben, wie sie sind.
// JQL in Segmente teilen: ungerade Positionen sind Zeichenketten in
// Anfuehrungszeichen, dort wird nie ersetzt (ein Suchwert wie "Maßnahme in
// Arbeit" ist kein Feldname).
function jqlTeile(q) {
  return String(q).split(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/);
}
async function prepareJql(jql, callerName) {
  let q = String(jql);
  if (/currentUser\(\)/i.test(q)) {
    const hint = 'Fuer currentUser() brauche ich den Jira-Nutzer der fragenden Person; nutze list_users mit der Mailadresse und setze die accountId ein.';
    const cn = String(callerName || '').trim();
    if (!cn) return { error: hint };
    const u = await resolveUser(cn, 'Fragende Person', true);
    if (!u.accountId) return { error: hint + ' (' + u.error + ')' };
    const t0 = jqlTeile(q);
    for (let i = 0; i < t0.length; i += 2) t0[i] = t0[i].replace(/currentUser\(\)/gi, '"' + u.accountId + '"');
    q = t0.join('');
  }
  const idx = await fieldIndex();
  if (idx.list.length) {
    const OPS = '(?=\\s*(?:=|!=|~|!~|>=|<=|>|<|\\bin\\b|\\bnot\\s+in\\b|\\bis\\b|\\bwas\\b|\\bchanged\\b))';
    const toCf = function (name) {
      const id = resolveField(idx, name);
      const m = id ? String(id).match(/^customfield_(\d+)$/i) : null;
      return m ? 'cf[' + m[1] + ']' : null;
    };
    const OPS_START = /^\s*(?:=|!=|~|!~|>=|<=|>|<|\bin\b|\bnot\s+in\b|\bis\b|\bwas\b|\bchanged\b)/i;
    const teile = jqlTeile(q);
    const bare = new RegExp('(^|[\\s(])([A-Za-z\\u00C0-\\u024F][\\w\\u00C0-\\u024F]*)' + OPS, 'gi');
    for (let i = 0; i < teile.length; i++) {
      if (i % 2 === 1) {
        // Feldname in Anfuehrungszeichen, nur wenn direkt ein Operator folgt
        if (!OPS_START.test(teile[i + 1] || '')) continue;
        const cf = toCf(teile[i].slice(1, -1));
        if (cf) teile[i] = cf;
      } else {
        teile[i] = teile[i].replace(bare, function (all, pre, name) { const cf = toCf(name); return cf ? pre + cf : all; });
      }
    }
    q = teile.join('');
  }
  return { jql: q };
}

// --- Faelligkeit (JJJJ-MM-TT), Aliasse due und due_date; "none" loescht ---
function parseDuedate(inp) {
  let raw = inp.duedate;
  if (raw === undefined || raw === null || String(raw).trim() === '') raw = inp.due_date;
  if (raw === undefined || raw === null || String(raw).trim() === '') raw = inp.due;
  if (raw === undefined || raw === null || String(raw).trim() === '') return { value: undefined };
  const s = String(raw).trim();
  if (/^(none|null|-|leer|keins)$/i.test(s)) return { value: null };
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return { error: 'duedate muss das Format JJJJ-MM-TT haben (z. B. 2026-09-30), nicht "' + s + '".' };
  return { value: s };
}

// --- custom_fields: Objekt oder JSON-String, Schluessel Klarname oder Id ---
async function parseCustomFields(raw) {
  let cf = raw;
  if (typeof cf === 'string') {
    if (!cf.trim()) return { cf: null };
    try { cf = JSON.parse(cf); } catch (e) { return { error: 'custom_fields ist kein gueltiges JSON: ' + e.message }; }
  }
  if (!cf || typeof cf !== 'object' || Array.isArray(cf) || !Object.keys(cf).length) return { cf: null };
  const idx = await fieldIndex();
  const out = {};
  for (const k of Object.keys(cf)) {
    const id = resolveField(idx, k);
    if (!id) return { error: unknownFieldError(idx, k) };
    out[id] = cf[k];
  }
  return { cf: out };
}
async function loadEditMetaFields(key) {
  const r = await helpers.httpRequest({ method: 'GET', url: API + '/issue/' + encodeURIComponent(key) + '/editmeta', headers: authHeaders });
  return (r && r.fields) || {};
}

// Jira-Fehlerkoerper lesbar machen: errorMessages plus Fehler je Feld
function jiraErrorText(status, body) {
  let b = body;
  if (typeof b === 'string') {
    try { b = JSON.parse(b); } catch (e) { return 'HTTP ' + status + ': ' + b.substring(0, 500); }
  }
  const parts = [];
  if (b && Array.isArray(b.errorMessages)) for (const m of b.errorMessages) parts.push(String(m));
  if (b && b.errors && typeof b.errors === 'object') for (const k of Object.keys(b.errors)) parts.push(k + ': ' + b.errors[k]);
  return 'HTTP ' + status + ': ' + (parts.length ? parts.join('; ') : JSON.stringify(b === undefined ? null : b).substring(0, 500));
}

// === list_projects ===
if (action === 'list_projects') {
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/project/search?maxResults=50&expand=lead', headers: authHeaders });
    const items = r.values || [];
    if (items.length === 0) return [{ json: { result: 'No projects.' } }];
    let out = 'Projects (' + items.length + (r.total ? ' of ' + r.total : '') + '):\n';
    for (const p of items) {
      out += '  ' + p.key + ' — ' + p.name + ' (' + (p.projectTypeKey || '?') + ')';
      if (p.lead && p.lead.displayName) out += ' lead: ' + p.lead.displayName;
      out += '\n';
    }
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Jira list_projects failed: ' + err.message } }];
  }

// === search_issues ===
} else if (action === 'search_issues') {
  const jql = input.jql;
  if (!jql) return [{ json: { error: 'Parameter "jql" is required. Examples: "project = KAN ORDER BY created DESC", "assignee = \\"Vorname Nachname\\" AND status != Done".' } }];
  const limit = Math.min(parseInt(input.limit || input.max_results) || 20, 100);
  const DEFAULT_FIELDS = ['summary', 'status', 'assignee', 'priority', 'issuetype', 'created', 'updated'];
  const fp = await parseFieldsParam(input.fields);
  if (fp.error) return [{ json: { error: 'Jira search_issues: ' + fp.error } }];
  const fields = fp.all ? '*all' : DEFAULT_FIELDS.concat(fp.ids.filter(id => !DEFAULT_FIELDS.includes(id))).join(',');
  const pj = await prepareJql(jql, input.caller_name);
  if (pj.error) return [{ json: { error: 'Jira search_issues: ' + pj.error } }];
  try {
    const qs = buildQs({ jql: pj.jql, maxResults: String(limit), fields });
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/search/jql?' + qs, headers: authHeaders });
    const items = r.issues || [];
    if (items.length === 0) return [{ json: { result: 'No issues matched JQL: ' + pj.jql } }];
    const idx = await fieldIndex();
    let out = 'Issues (' + items.length + '):\n';
    for (const it of items) {
      out += fmtIssueLine(it) + '\n';
      const extra = extraFieldLines(idx, it.fields || {}, fp.ids, DEFAULT_FIELDS);
      if (extra.length) out += '    ' + extra.join(' | ') + '\n';
    }
    if (pj.jql !== String(jql)) out += '\n(JQL used: ' + pj.jql + ')\n';
    if (r.nextPageToken) out += '\n(more results available — refine JQL or increase limit)\n';
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    const msg = err.response && err.response.body ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Jira search_issues failed: ' + msg } }];
  }

// === get_issue ===
} else if (action === 'get_issue') {
  const key = input.key;
  if (!key) return [{ json: { error: 'Parameter "key" is required (e.g. KAN-1).' } }];
  // Basisfelder plus alles, was ueber "fields" angefragt wurde (Klarname, Id oder *all)
  const BASE_FIELDS = ['summary', 'description', 'status', 'assignee', 'reporter', 'priority', 'issuetype', 'labels', 'duedate', 'created', 'updated', 'comment', 'issuelinks', 'parent'];
  const fp = await parseFieldsParam(input.fields);
  if (fp.error) return [{ json: { error: 'Jira get_issue: ' + fp.error } }];
  // Ohne ausdrueckliche Feldangabe zusaetzlich *navigable: dann kommen Custom-Felder
  // mit Wert (z. B. Massnahme) von selbst mit. Florian, 07.09.2026: "get_issue liefert
  // nur Standardfelder". Die Ausgabe kuerzt lange Werte, die Antwort bleibt lesbar.
  const fieldList = fp.all ? '*all'
    : (fp.ids.length ? BASE_FIELDS.concat(fp.ids.filter(id => !BASE_FIELDS.includes(id))).join(',')
                     : BASE_FIELDS.concat(['*navigable']).join(','));
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/issue/' + encodeURIComponent(key) + '?fields=' + fieldList, headers: authHeaders });
    const f = r.fields || {};
    let out = '**' + r.key + '** — ' + (f.summary || '') + '\n';
    out += 'Status: ' + (f.status ? f.status.name : '?') + '\n';
    out += 'Type: ' + (f.issuetype ? f.issuetype.name : '?') + '\n';
    if (f.assignee) out += 'Assignee: ' + f.assignee.displayName + ' (accountId: ' + f.assignee.accountId + ')\n';
    else out += 'Assignee: unassigned\n';
    if (f.reporter) out += 'Reporter: ' + f.reporter.displayName + '\n';
    if (f.priority) out += 'Priority: ' + f.priority.name + '\n';
    if (f.labels && f.labels.length) out += 'Labels: ' + f.labels.join(', ') + '\n';
    if (f.parent) out += 'Parent: ' + f.parent.key + ' — ' + (f.parent.fields ? f.parent.fields.summary : '') + '\n';
    if (f.duedate) out += 'Due: ' + String(f.duedate).substring(0, 10) + '\n';
    if (f.created) out += 'Created: ' + f.created.substring(0, 10) + '\n';
    if (f.updated) out += 'Updated: ' + f.updated.substring(0, 10) + '\n';
    // Angefragte Felder und alle Custom-Felder mit Wert unter ihrem Klarnamen
    const needIdx = fp.ids.length > 0 || Object.keys(f).some(k => /^customfield_/i.test(k) && hasValue(f[k]));
    if (needIdx) {
      const extra = extraFieldLines(await fieldIndex(), f, fp.ids, BASE_FIELDS);
      if (extra.length) out += '\nFields:\n' + extra.map(l => '  ' + l).join('\n') + '\n';
    }
    const desc = adfToText(f.description);
    if (desc) out += '\nDescription:\n' + desc + '\n';
    if (f.issuelinks && f.issuelinks.length) {
      out += '\nLinks:\n';
      for (const l of f.issuelinks) {
        const other = l.outwardIssue || l.inwardIssue;
        const dir = l.outwardIssue ? l.type.outward : l.type.inward;
        if (other) out += '  ' + dir + ' ' + other.key + ' — ' + (other.fields ? other.fields.summary : '') + '\n';
      }
    }
    if (f.comment && f.comment.comments && f.comment.comments.length) {
      out += '\nComments (' + f.comment.comments.length + '):\n';
      for (const c of f.comment.comments.slice(0, 5)) {
        const who = c.author ? c.author.displayName : 'unknown';
        out += '  ' + who + ' (' + (c.created || '').substring(0, 10) + '): ' + adfToText(c.body).substring(0, 200) + '\n';
      }
      if (f.comment.comments.length > 5) out += '  ... (' + (f.comment.comments.length - 5) + ' more — use list_comments)\n';
    }
    out += '\n' + issueUrl(r.key);
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Jira get_issue failed: ' + err.message } }];
  }

// === create_issue ===
} else if (action === 'create_issue') {
  const project = input.project;
  const summary = input.summary;
  if (!project) return [{ json: { error: 'Parameter "project" is required (project key, e.g. KAN).' } }];
  if (!summary) return [{ json: { error: 'Parameter "summary" is required.' } }];
  // Vorgangstyp vor dem Absenden gegen das Projekt pruefen. Ein geratener Typ
  // lief bisher in einen 400er, dessen Hinweis die Pflichtfelder eines anderen
  // Typs zeigte; daraus wurde "nur Arbeitspaket erlaubt" (SLT, 09.09.2026).
  let issuetype = String(input.issuetype || '').trim();
  let typen = [];
  try { typen = await ladeTypen(project); } catch (e) { typen = []; }
  // Ohne Angabe: der einzige Typ der Ebene 0 (bei SLT "Aufgabe"); "Task" als
  // Vorgabe gibt es in deutschsprachigen Projekten nicht.
  if (!issuetype && typen.length) {
    const ebene0 = typen.filter(x => ((x.hierarchyLevel !== undefined && x.hierarchyLevel !== null) ? x.hierarchyLevel : (x.subtask ? -1 : 0)) === 0);
    if (ebene0.length === 1) issuetype = ebene0[0].name;
    else return [{ json: { error: 'Jira create_issue: Bitte issuetype angeben. Erlaubt im Projekt ' + project.toUpperCase() + ': ' + typen.map(typLabel).join(', ') + '.' } }];
  }
  if (!issuetype) issuetype = 'Task';
  if (typen.length) {
    const want = issuetype.toLowerCase();
    const typ = typen.find(x => String(x.name || '').toLowerCase() === want);
    if (!typ) {
      return [{ json: { error: 'Jira create_issue: Vorgangstyp "' + issuetype + '" gibt es im Projekt ' + project.toUpperCase() + ' nicht. Erlaubt: ' +
        typen.map(typLabel).join(', ') + '. Typ genau so uebernehmen, nicht raten.' } }];
    }
    issuetype = typ.name;
    const lvl = (typ.hierarchyLevel !== undefined && typ.hierarchyLevel !== null) ? typ.hierarchyLevel : (typ.subtask ? -1 : 0);
    if (lvl < 0 && !parentKey(input.parent)) {
      return [{ json: { error: 'Jira create_issue: Vorgangstyp "' + typ.name + '" braucht ein uebergeordnetes Ticket (parent). Bitte den Schluessel angeben.' } }];
    }
  }
  const fields = { project: { key: project.toUpperCase() }, summary, issuetype: { name: issuetype } };
  if (input.description) {
    try { fields.description = await textToAdf(input.description); } catch (e) { return [{ json: { error: 'Jira create_issue: ' + e.message } }]; }
  }
  let bearbeiter = '';
  if (input.assignee && String(input.assignee).trim()) {
    const u = await resolveUser(input.assignee, 'Assignee');
    if (!u.accountId) return [{ json: { error: 'Jira create_issue: ' + u.error } }];
    fields.assignee = { accountId: u.accountId };
    bearbeiter = u.displayName || u.accountId;
  }
  if (input.priority) fields.priority = { name: input.priority };
  if (input.labels) fields.labels = String(input.labels).split(',').map(l => l.trim()).filter(Boolean);
  const pk = parentKey(input.parent);
  if (pk) fields.parent = { key: pk };
  const due = parseDuedate(input);
  if (due.error) return [{ json: { error: 'Jira create_issue: ' + due.error } }];
  if (due.value) fields.duedate = due.value;
  // Feldschema hoechstens einmal laden, gemeinsam fuer custom_fields und Prioritaet
  let _meta = null;
  const getMeta = async function () {
    if (_meta === null) {
      try { _meta = await loadCreateMetaFields(project, issuetype); } catch (e) { _meta = {}; }
    }
    return _meta;
  };

  if (input.custom_fields) {
    // Projektspezifische Pflicht-/Zusatzfelder. Ein einfacher Wert genuegt,
    // z. B. {"customfield_10047": "Digitale Projekte"} oder mit Klarnamen
    // {"Abteilung": "Digitale Projekte"} - die Form (Liste, Objekt, String)
    // wird aus dem Feldschema abgeleitet.
    const p = await parseCustomFields(input.custom_fields);
    if (p.error) return [{ json: { error: 'Jira create_issue: ' + p.error } }];
    if (p.cf) {
      const meta = await getMeta();
      const ru = await resolveUserFields(p.cf, meta);
      if (ru.error) return [{ json: { error: 'Jira create_issue: ' + ru.error } }];
      Object.assign(fields, await shapeCustomFields(p.cf, project, issuetype, meta));
    }
  }

  // Prioritaet gegen die Projektkonfiguration pruefen. Ein ungueltiger Wert
  // liess bisher das gesamte Anlegen scheitern, obwohl das Feld nebensaechlich
  // ist - und die eigentliche Fehlerursache ging in der Doppelmeldung unter.
  let priorityNote = '';
  if (input.priority) {
    const meta = await getMeta();
    const av = ((meta.priority || {}).allowedValues) || [];
    if (av.length) {
      const want = String(input.priority).trim().toLowerCase();
      const hit = av.find(v => String(v.name || v.value || '').toLowerCase() === want);
      if (hit) {
        fields.priority = { name: hit.name || hit.value };
      } else {
        delete fields.priority;
        priorityNote = ' (Hinweis: Prioritaet "' + input.priority + '" gibt es in diesem Projekt nicht, erlaubt sind ' +
          av.map(v => v.name || v.value).filter(Boolean).join(' | ') + '. Das Ticket wurde ohne Prioritaet angelegt.)';
      }
    }
  }
  try {
    const r = await helpers.httpRequest({ method: 'POST', url: API + '/issue', headers: jsonHeaders, body: JSON.stringify({ fields }), returnFullResponse: true, ignoreHttpStatusErrors: true });
    const rb = (r && r.body !== undefined) ? r.body : r;
    const status = (r && r.statusCode) ? r.statusCode : 200;
    // Bearbeiter in der Erfolgsmeldung: eine Fehlzuweisung faellt so beim ersten
    // Ticket auf, nicht erst nach vierzehn.
    if (status < 300 && rb && rb.key) return [{ json: { result: 'Issue created: ' + rb.key + ' (type: ' + issuetype + ', summary: "' + summary + '"' +
      (bearbeiter ? ', assignee: ' + bearbeiter : ', unassigned') + (pk ? ', parent: ' + pk : '') + ')' + priorityNote + '\n' + issueUrl(rb.key) } }];
    // Fehler: Jira-Response-Body durchreichen und Pflichtfelder ermitteln, damit sich der Agent korrigieren kann
    const detail = typeof rb === 'string' ? rb : JSON.stringify(rb);
    let hint = '';
    try {
      const tlist = await ladeTypen(project);
      const t = tlist.find(x => x.name && x.name.toLowerCase() === issuetype.toLowerCase());
      if (t) {
        const meta = await helpers.httpRequest({ method: 'GET', url: API + '/issue/createmeta/' + encodeURIComponent(project.toUpperCase()) + '/issuetypes/' + encodeURIComponent(t.id), headers: jsonHeaders });
        const flist = meta.fields || meta.values || [];
        const req = flist.filter(fl => fl.required && !fl.hasDefaultValue).map(fl => {
          let s = fl.name + ' (' + (fl.fieldId || fl.key || '?') + ')';
          const sch = fl.schema || {};
          if (sch.type === 'array') s += ' [erwartet eine Liste]';
          // Vollstaendig zeigen: eine gekuerzte Liste hat den Agenten schon zu der
          // falschen Aussage verleitet, ein Wert sei nicht erlaubt.
          const all = (fl.allowedValues || []).map(v => v.value || v.name).filter(Boolean);
          const shown = all.slice(0, 30);
          if (shown.length) {
            s += ' erlaubte Werte: ' + shown.join(' | ');
            if (all.length > shown.length) s += ' ... (' + shown.length + ' von ' + all.length + ' angezeigt)';
          }
          return s;
        });
        if (req.length) hint = ' | Pflichtfelder laut Jira fuer Typ "' + t.name + '": ' + req.join(', ') + '. Custom-Felder setzt du ueber den Parameter custom_fields; ein einfacher Wert genuegt, die Form wird automatisch an das Feldschema angepasst, z. B. custom_fields mit customfield_10047 auf den gewuenschten Wert.';
      }
    } catch (_e) {}
    return [{ json: { error: 'Jira create_issue failed (HTTP ' + status + '): ' + detail + hint } }];
  } catch (err) {
    const _r = err.response || (err.cause && err.cause.response) || {};
    const msg = (_r.body || _r.data) ? JSON.stringify(_r.body || _r.data) : err.message;
    return [{ json: { error: 'Jira create_issue failed: ' + msg } }];
  }

// === update_issue ===
} else if (action === 'update_issue') {
  // key oder keys (Kommaliste oder Array): mehrere Tickets laufen hier in einer
  // Schleife, damit das Modell nicht je Ticket eine Runde braucht. Nach dem
  // zweiten identischen Fehler wird abgebrochen.
  let rawKeys = (input.keys !== undefined && input.keys !== null && input.keys !== '') ? input.keys : input.key;
  // Der MCP-Client schickt Listen als JSON-String
  if (typeof rawKeys === 'string' && rawKeys.trim().startsWith('[')) { try { rawKeys = JSON.parse(rawKeys); } catch (e) { /* dann als Kommaliste */ } }
  let keys = Array.isArray(rawKeys) ? rawKeys : String(rawKeys || '').split(',');
  keys = keys.map(k => String(k || '').trim()).filter(Boolean);
  if (!keys.length) return [{ json: { error: 'Parameter "key" is required (e.g. KAN-1). For several issues pass "keys" as a comma-separated list.' } }];
  const fields = {};
  let bearbeiterName = '';
  if (input.summary) fields.summary = input.summary;
  if (input.description) {
    try { fields.description = await textToAdf(input.description); } catch (e) { return [{ json: { error: 'Jira update_issue: ' + e.message } }]; }
  }
  // Leerer assignee heisst "nicht anfassen" (der MCP-Client fuellt fehlende
  // Parameter mit ''), zum Entfernen ausdruecklich "none" schicken.
  if (input.assignee !== undefined && input.assignee !== null && String(input.assignee).trim() !== '') {
    const a = String(input.assignee).trim();
    if (/^(none|null|unassign|unassigned|-|niemand)$/i.test(a)) fields.assignee = null;
    else {
      const u = await resolveUser(a, 'Assignee');
      if (!u.accountId) return [{ json: { error: 'Jira update_issue: ' + u.error } }];
      fields.assignee = { accountId: u.accountId };
      bearbeiterName = u.displayName || u.accountId;
    }
  }
  if (input.priority) fields.priority = { name: input.priority };
  if (input.labels) fields.labels = String(input.labels).split(',').map(l => l.trim()).filter(Boolean);
  const due = parseDuedate(input);
  if (due.error) return [{ json: { error: 'Jira update_issue: ' + due.error } }];
  if (due.value !== undefined) fields.duedate = due.value;
  let custom = null;
  if (input.custom_fields) {
    const p = await parseCustomFields(input.custom_fields);
    if (p.error) return [{ json: { error: 'Jira update_issue: ' + p.error } }];
    custom = p.cf;
  }
  if (Object.keys(fields).length === 0 && !custom) return [{ json: { error: 'Provide at least one field: summary, description, assignee (name, email or accountId; "none" to unassign), priority, labels, duedate (YYYY-MM-DD), custom_fields.' } }];
  const results = [];
  let prevErr = null;
  let okCount = 0;
  let lastErr = null;
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const body = Object.assign({}, fields);
    let errText = null;
    if (custom) {
      // Form je Ticket aus editmeta ableiten (Liste, Option, Nutzer, Datum)
      const cf = Object.assign({}, custom);
      let meta = {};
      try { meta = await loadEditMetaFields(key); } catch (e) { meta = {}; }
      const ru = await resolveUserFields(cf, meta);
      if (ru.error) errText = ru.error;
      else Object.assign(body, await shapeCustomFields(cf, null, null, meta));
    }
    if (!errText) {
      try {
        const r = await helpers.httpRequest({ method: 'PUT', url: API + '/issue/' + encodeURIComponent(key), headers: jsonHeaders, body: JSON.stringify({ fields: body }), returnFullResponse: true, ignoreHttpStatusErrors: true });
        const status = (r && r.statusCode) ? r.statusCode : 200;
        if (status >= 300) errText = jiraErrorText(status, r.body);
      } catch (err) {
        const _r = err.response || (err.cause && err.cause.response) || {};
        errText = (_r.body || _r.data) ? jiraErrorText(_r.statusCode || _r.status || '?', _r.body || _r.data) : err.message;
      }
    }
    if (!errText) { okCount++; prevErr = null; results.push(key + ': aktualisiert' + (bearbeiterName ? ' (Bearbeiter: ' + bearbeiterName + ')' : (fields.assignee === null ? ' (Bearbeiter entfernt)' : '')) + '. ' + issueUrl(key)); continue; }
    lastErr = errText;
    results.push(key + ': Fehler ' + errText);
    // Ein 404 gilt nur fuer diesen Vorgang (Ticket gibt es nicht oder ist nicht
    // sichtbar) und ist kein Grund, die uebrigen abzubrechen.
    const nurDieserKey = /\b404\b/.test(errText) || /does not exist/i.test(errText);
    if (errText === prevErr && !nurDieserKey) {
      const rest = keys.length - i - 1;
      results.push('abgebrochen, gleicher Fehler zweimal' + (rest ? ' (' + rest + ' Ticket(s) nicht bearbeitet)' : ''));
      break;
    }
    prevErr = errText;
  }
  if (keys.length === 1) {
    if (lastErr) return [{ json: { error: 'Jira update_issue failed: ' + lastErr } }];
    return [{ json: { result: 'Issue ' + keys[0] + ' updated' + (bearbeiterName ? ' (Bearbeiter: ' + bearbeiterName + ')' : (fields.assignee === null ? ' (Bearbeiter entfernt)' : '')) + '.\n' + issueUrl(keys[0]) } }];
  }
  const summary = 'Update: ' + okCount + ' of ' + keys.length + ' issues updated.\n' + results.join('\n');
  if (okCount === 0) return [{ json: { error: 'Jira update_issue failed: ' + summary } }];
  return [{ json: { result: truncate(summary) } }];

// === add_comment ===
} else if (action === 'add_comment') {
  const key = input.key;
  const text = input.text;
  if (!key) return [{ json: { error: 'Parameter "key" is required.' } }];
  if (!text) return [{ json: { error: 'Parameter "text" is required.' } }];
  try {
    const r = await helpers.httpRequest({ method: 'POST', url: API + '/issue/' + encodeURIComponent(key) + '/comment', headers: jsonHeaders, body: JSON.stringify({ body: await textToAdf(text) }) });
    return [{ json: { result: 'Comment added to ' + key + ' (id: ' + r.id + ')' } }];
  } catch (err) {
    return [{ json: { error: 'Jira add_comment failed: ' + err.message } }];
  }

// === list_comments ===
} else if (action === 'list_comments') {
  const key = input.key;
  if (!key) return [{ json: { error: 'Parameter "key" is required.' } }];
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/issue/' + encodeURIComponent(key) + '/comment?maxResults=50', headers: authHeaders });
    const items = r.comments || [];
    if (items.length === 0) return [{ json: { result: 'No comments on ' + key + '.' } }];
    let out = 'Comments on ' + key + ' (' + items.length + '):\n\n';
    for (const c of items) {
      const who = c.author ? c.author.displayName : 'unknown';
      const when = (c.created || '').substring(0, 10);
      out += who + ' (' + when + '):\n  ' + adfToText(c.body) + '\n\n';
    }
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Jira list_comments failed: ' + err.message } }];
  }

// === transition_issue ===
} else if (action === 'transition_issue') {
  const key = input.key;
  const target = input.transition;
  if (!key) return [{ json: { error: 'Parameter "key" is required.' } }];
  if (!target) return [{ json: { error: 'Parameter "transition" is required (status name or transition id). Use list_transitions to see options.' } }];
  try {
    const tList = await helpers.httpRequest({ method: 'GET', url: API + '/issue/' + encodeURIComponent(key) + '/transitions', headers: authHeaders });
    const transitions = tList.transitions || [];
    let match = transitions.find(t => t.id === String(target));
    if (!match) {
      const t = String(target).toLowerCase();
      match = transitions.find(x => x.name.toLowerCase() === t) || transitions.find(x => x.to && x.to.name.toLowerCase() === t) || transitions.find(x => x.name.toLowerCase().includes(t));
    }
    if (!match) {
      const names = transitions.map(x => x.name).join(', ');
      return [{ json: { error: 'No transition matching "' + target + '". Available: ' + names } }];
    }
    await helpers.httpRequest({ method: 'POST', url: API + '/issue/' + encodeURIComponent(key) + '/transitions', headers: jsonHeaders, body: JSON.stringify({ transition: { id: match.id } }) });
    return [{ json: { result: key + ' transitioned via "' + match.name + '" -> ' + match.to.name + '.' } }];
  } catch (err) {
    return [{ json: { error: 'Jira transition_issue failed: ' + err.message } }];
  }

// === list_transitions ===
} else if (action === 'list_transitions') {
  const key = input.key;
  if (!key) return [{ json: { error: 'Parameter "key" is required.' } }];
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/issue/' + encodeURIComponent(key) + '/transitions', headers: authHeaders });
    const items = r.transitions || [];
    if (items.length === 0) return [{ json: { result: 'No transitions available from current state.' } }];
    let out = 'Available transitions for ' + key + ':\n';
    for (const t of items) out += '  [' + t.id + '] "' + t.name + '" — moves to: ' + t.to.name + '\n';
    return [{ json: { result: out } }];
  } catch (err) {
    return [{ json: { error: 'Jira list_transitions failed: ' + err.message } }];
  }

// === list_issue_types ===
} else if (action === 'list_issue_types') {
  const project = input.project;
  if (!project) return [{ json: { error: 'Parameter "project" is required (project key, e.g. KAN).' } }];
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/issue/createmeta/' + encodeURIComponent(project.toUpperCase()) + '/issuetypes', headers: authHeaders });
    const items = r.issueTypes || r.values || [];
    if (items.length === 0) return [{ json: { result: 'No issue types for project ' + project + '.' } }];
    let out = 'Issue types for ' + project.toUpperCase() + ':\n';
    // Ebene mit ausgeben (hierarchyLevel: 1 = Epic/Arbeitspaket, 0 = Aufgabe,
    // -1 = Unteraufgabe), damit die Kette nicht geraten werden muss.
    for (const t of items) out += '  ' + typLabel(t) + (t.description ? ' — ' + t.description : '') + '\n';
    out += 'Regel: Typ genau so uebernehmen wie hier gelistet. Ebene -1 braucht parent (ein Ticket der Ebene 0), Ebene 0 kann unter Ebene 1 haengen.';
    return [{ json: { result: out } }];
  } catch (err) {
    return [{ json: { error: 'Jira list_issue_types failed: ' + err.message } }];
  }

// === link_issues ===
} else if (action === 'link_issues') {
  const from = input.from;
  const to = input.to;
  const type = input.type || 'Relates';
  if (!from || !to) return [{ json: { error: 'Parameters "from" and "to" are required (issue keys, e.g. KAN-1 and KAN-2).' } }];
  try {
    const body = { type: { name: type }, inwardIssue: { key: to }, outwardIssue: { key: from } };
    await helpers.httpRequest({ method: 'POST', url: API + '/issueLink', headers: jsonHeaders, body: JSON.stringify(body) });
    return [{ json: { result: from + ' linked to ' + to + ' (type: ' + type + ').' } }];
  } catch (err) {
    const msg = err.response && err.response.body ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Jira link_issues failed: ' + msg + '. Valid types: Blocks, Duplicate, Relates, Cloners.' } }];
  }

// === list_users ===
} else if (action === 'list_users') {
  const query = input.query;
  if (!query) return [{ json: { error: 'Parameter "query" is required (name or email fragment).' } }];
  const limit = Math.min(parseInt(input.limit) || 10, 50);
  try {
    const qs = buildQs({ query, maxResults: String(limit) });
    const r = await helpers.httpRequest({ method: 'GET', url: API + '/user/search?' + qs, headers: authHeaders });
    const items = Array.isArray(r) ? r : [];
    if (items.length === 0) return [{ json: { result: 'No users matched "' + query + '".' } }];
    let out = 'Users (' + items.length + '):\n';
    for (const u of items) {
      out += '  ' + u.displayName + ' (accountId: ' + u.accountId + (u.emailAddress ? ', ' + u.emailAddress : '') + ')\n';
    }
    return [{ json: { result: out } }];
  } catch (err) {
    return [{ json: { error: 'Jira list_users failed: ' + err.message } }];
  }

// === list_fields ===
} else if (action === 'list_fields') {
  const idx = await fieldIndex();
  if (!idx.list.length) return [{ json: { error: 'Jira list_fields failed: die Feldliste (GET /field) konnte nicht geladen werden.' } }];
  const filterRaw = String(input.filter || '').trim();
  const filter = filterRaw.toLowerCase();
  const items = idx.list.filter(f => !filter || String(f.name || '').toLowerCase().includes(filter) || String(f.id).toLowerCase().includes(filter));
  items.sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
  if (!items.length) return [{ json: { result: 'No fields matched "' + filterRaw + '". Try a shorter fragment of the name.' } }];
  const MAX = 60;
  let out = 'Fields (' + Math.min(items.length, MAX) + ' of ' + items.length + (filter ? ', filter "' + filterRaw + '"' : '') + '):\n';
  out += '  Name | Id | Typ\n';
  for (const f of items.slice(0, MAX)) out += '  ' + (f.name || '?') + ' | ' + f.id + ' | ' + fieldTypeLabel(f) + '\n';
  if (items.length > MAX) out += '  ... (' + (items.length - MAX) + ' more, narrow down with filter)\n';
  return [{ json: { result: truncate(out) } }];

} else {
  return [{ json: { error: 'Unknown action: "' + action + '". Available: list_projects, search_issues, get_issue, create_issue, update_issue, add_comment, transition_issue, list_users, list_comments, list_transitions, list_issue_types, link_issues, list_fields.' } }];
}
